using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = httpFactory.CreateClient("api");
        var post = await client.GetFromJsonAsync<Post>($"/posts/{id}", cancellationToken);
        return $"Title: {post!.Title}\n\n{post.Body}";
    }

    [McpServerTool, Description("Search posts by a keyword in the title. Returns matching post titles and IDs.")]
    public async Task<string> SearchPosts(
        [Description("Keyword to search for in post titles")] string keyword,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching posts for '{Keyword}'", keyword);
        var client = httpFactory.CreateClient("api");
        var posts = await client.GetFromJsonAsync<Post[]>("/posts", cancellationToken);
        var matches = posts!
            .Where(p => p.Title.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .Select(p => $"[{p.Id}] {p.Title}");
        var result = string.Join("\n", matches);
        return string.IsNullOrEmpty(result) ? "No posts found." : result;
    }

    [McpServerTool, Description("List comments on a specific post.")]
    public async Task<string> GetPostComments(
        [Description("The numeric ID of the post")] int postId,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var comments = await client.GetFromJsonAsync<Comment[]>(
            $"/posts/{postId}/comments", cancellationToken);
        return string.Join("\n\n", comments!.Select(c =>
            $"From: {c.Email}\n{c.Body}"));
    }
}

public record Post(
    [property: JsonPropertyName("id")] int Id,
    [property: JsonPropertyName("title")] string Title,
    [property: JsonPropertyName("body")] string Body);

public record Comment(
    [property: JsonPropertyName("email")] string Email,
    [property: JsonPropertyName("body")] string Body);

